FUNCTION F_ClientesAlteracoesSalvar
***********************************
PRIVATE ARRAY aErros[1], lSucesso, oErro

   lSucesso = .F.
   oErro    = .NULL.

   IF NOT USED("Clientes") THEN
      RETURN(.F.)
   ENDIF

   BEGIN TRANSACTION

   TRY

      SELECT Clientes

      IF TABLEUPDATE(.T., .F., "Clientes") THEN

         END TRANSACTION

         lSucesso = .T.

      ELSE

         ROLLBACK

         AERROR(aErros)

         MESSAGEBOX( ;
            "Não foi possível salvar as alterações: " + ;
            TRANSFORM(aErros[1, 2]), ;
            16, ;
            "Erro de atualização" ;
         )

      ENDIF

   CATCH TO oErro

      ROLLBACK

      MESSAGEBOX( ;
         oErro.Message, ;
         16, ;
         "Erro durante a transação" ;
      )

      lSucesso = .F.

   ENDTRY

   RETURN(lSucesso)

ENDFUNC"}

